ion_id,\n          client_net_address\n        FROM monitoring.tcp_connections c\n        WHERE (\n          last_read > (\n            SELECT MAX(last_read) FROM monitoring.tcp_connections b WHERE c.server = b.server\n          ) - INTERVAL '1 minute'\n          OR\n          last_write > (\n            SELECT MAX(last_write) FROM monitoring.tcp_connections b WHERE c.server = b.server\n          ) - INTERVAL '1 minute'\n        )\n        AND connect_time > (\n          SELECT MAX(connect_time) FROM monitoring.tcp_connections\n        ) - INTERVAL '1 minute'\n        AND client_net_address NOT IN (\n          SELECT client_net_address FROM monitoring.tcp_connections \n          WHERE connect_time < (\n            SELECT MAX(connect_time) FROM monitoring.tcp_connections\n          ) - INTERVAL '1 day'\n        )\n      ) C \n      WHERE SEQ = 1\n    ) A ON A.server = w.server AND A.session_Id = w.session_id\n  ) D \n  WHERE D.SEQ = 1\n) B ON B.server = A.server AND B.client_net_address = A.client_net_address	1	t
